-- m20220101_000007_strategy: frozen on 11 November 2026 from the statements its sea-orm-migration `up` ran on PostgreSQL 18,
-- in order. Never edit it: `_sqlx_migrations` holds its checksum. A change is a new migration.
--
-- What the Rust migration said of itself:
--
-- Migration: the PPM Phase-C **strategy** tables (spec/15-roadmap
-- PPM-2/4/5/11) — `ideas` (the pre-proposal funnel), `scenarios`
-- (what-if portfolios), `objectives` + `objective_links` (OKR
-- alignment), and `benefits` (value realization). Money stays
-- integer minor units + ISO-4217 (the Phase-A posture).

CREATE TABLE IF NOT EXISTS "ideas" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "title" varchar NOT NULL, "pitch" text NULL, "tags" jsonb NOT NULL, "votes" integer NOT NULL, "status" varchar NOT NULL, "converted_proposal_pid" uuid NULL, "deleted_at" timestamp with time zone NULL );

CREATE TABLE IF NOT EXISTS "scenarios" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "name" varchar NOT NULL, "description" text NULL, "members" jsonb NOT NULL, "budget_cap_minor" bigint NULL, "currency" varchar NULL, "must_include" jsonb NOT NULL, "status" varchar NOT NULL, "committed_at" timestamp with time zone NULL, "deleted_at" timestamp with time zone NULL );

CREATE TABLE IF NOT EXISTS "objectives" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "title" varchar NOT NULL, "description" text NULL, "period" varchar NULL, "deleted_at" timestamp with time zone NULL );

CREATE TABLE IF NOT EXISTS "objective_links" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "objective_pid" uuid NOT NULL, "plan_pid" uuid NOT NULL, "weight" integer NOT NULL );

CREATE TABLE IF NOT EXISTS "benefits" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "plan_pid" uuid NOT NULL, "title" varchar NOT NULL, "category" varchar NOT NULL, "currency" varchar NULL, "target_minor" bigint NULL, "realized_minor" bigint NOT NULL, "target_note" text NULL, "realized_note" text NULL, "expected_on" date NULL, "status" varchar NOT NULL, "deleted_at" timestamp with time zone NULL );

CREATE UNIQUE INDEX IF NOT EXISTS objective_links_pair ON objective_links (objective_pid, plan_pid);

CREATE INDEX IF NOT EXISTS objective_links_item ON objective_links (plan_pid);

CREATE INDEX IF NOT EXISTS benefits_item ON benefits (plan_pid);
